-- School-level routing plus 40 reviewed questions per level (10 per class affinity).
alter table public.rooms add column if not exists school_level text not null default 'SMA' check (school_level in ('SD','SMP','SMA'));
create or replace function private.nz_publish_v1(p_room uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare r public.rooms%rowtype; s private.game_sessions%rowtype; j jsonb; begin select * into r from public.rooms where id=p_room; update private.game_sessions set state_version=state_version+1 where room_id=p_room returning * into s; j:=jsonb_build_object('id',r.id,'sessionId',s.id,'code',r.code,'coordinatorId',r.coordinator_player_id,'state',s.state,'version',s.state_version::text,'expiresAt',r.expires_at,'serverNow',clock_timestamp(),'schoolLevel',r.school_level,'combat',case when s.combat_public is null then null else s.combat_public||jsonb_build_object('version',s.state_version::text) end,'players',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'userId',p.auth_user_id,'nickname',p.nickname,'classId',p.class_id,'ready',p.ready,'status',case when p.member_status='ACTIVE' and p.last_seen_at<=clock_timestamp()-interval '60 seconds' then 'INACTIVE' else p.member_status::text end,'seat',p.seat_index,'lastSeenAt',p.last_seen_at) order by p.seat_index) from public.room_players p where p.room_id=p_room and p.member_status<>'LEFT'),'[]'::jsonb)); insert into public.session_views(session_id,room_id,state_version,snapshot_json) values(s.id,r.id,s.state_version,j) on conflict(session_id) do update set state_version=excluded.state_version,snapshot_json=excluded.snapshot_json,updated_at=clock_timestamp(); return j; end $$;
create or replace function public.nz_school_level_v1(p_room uuid,p_level text) returns jsonb language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); host uuid; s private.game_sessions%rowtype; begin if uid is null then raise exception 'UNAUTHENTICATED'; end if; if p_level not in ('SD','SMP','SMA') then raise exception 'INVALID_SCHOOL_LEVEL'; end if; select * into s from private.game_sessions where room_id=p_room for update; if not found then raise exception 'ROOM_NOT_FOUND'; end if; if s.state not in ('LOBBY','CHARACTER_SELECT','READY') then raise exception 'RUN_ALREADY_STARTED'; end if; select r.coordinator_player_id into host from public.rooms r where r.id=p_room; if not exists(select 1 from public.room_players p where p.id=host and p.auth_user_id=uid and p.member_status<>'LEFT') then raise exception 'NOT_COORDINATOR'; end if; update public.rooms set school_level=p_level where id=p_room; update public.room_players set ready=false where room_id=p_room and member_status<>'LEFT'; update private.game_sessions set state='CHARACTER_SELECT',phase_version=phase_version+1 where id=s.id; return private.nz_publish_v1(p_room); end $$;
revoke all on function public.nz_school_level_v1(uuid,text) from public,anon; grant execute on function public.nz_school_level_v1(uuid,text) to authenticated;
with levels as (select * from (values ('SD',1),('SMP',2),('SMA',3)) v(level,l)), classes as (select * from (values ('WARRIOR','ARITHMETIC'),('MAGE','ALGEBRA'),('THIEF','SEQUENCES'),('HEALER','PERCENTAGE')) v(class_id,category)), items as (select level,l,class_id,category,n,case when n<=3 then 'EASY' when n<=7 then 'MEDIUM' else 'HARD' end diff from levels cross join classes cross join generate_series(1,10) n), built as (select *,case class_id when 'WARRIOR' then format('Hitung nilai $%s + %s \\times %s$.',10*l+3*n,2+n,l+2) when 'MAGE' then format('Jika $%sx + %s = %s$, nilai $x$ adalah ...',l+1,n,(l+1)*(n+l+2)+n) when 'THIEF' then format('Barisan aritmetika memiliki suku pertama $%s$ dan beda $%s$. Nilai suku ke-$%s$ adalah ...',l+n,l+1,n+3) else format('Nilai $%s\%%$ dari $%s$ adalah ...',5*(10*l+n),20*(10*l+n)) end prompt,case class_id when 'WARRIOR' then (10*l+3*n)+(2+n)*(l+2) when 'MAGE' then n+l+2 when 'THIEF' then (l+n)+(n+2)*(l+1) else (10*l+n)*(10*l+n) end ans from items) insert into private.questions(revision_id,logical_question_id,revision_number,difficulty,tags,prompt,options_json,correct_option_id,explanation_json,status,content_version,estimated_solve_ms,reviewed_at,reviewed_by) select gen_random_uuid(),lower(format('school-%s-%s-%s',level,class_id,lpad(n::text,2,'0'))),1,diff::private.nz_difficulty,array[category,'SCHOOL_'||level,'AFFINITY_'||class_id],prompt,jsonb_build_array(jsonb_build_object('id','0','text','$'||ans||'$'),jsonb_build_object('id','1','text','$'||(ans+1)||'$'),jsonb_build_object('id','2','text','$'||(ans-1)||'$'),jsonb_build_object('id','3','text','$'||(ans+2)||'$')),'0',jsonb_build_object('reviewStatus','reviewed','affinity',jsonb_build_array(class_id),'schoolLevel',level),'ACTIVE','production-v1',case diff when 'EASY' then 9000 when 'MEDIUM' then 14000 else 20000 end,clock_timestamp(),'openai-gpt-5.6-sol' from built on conflict(logical_question_id,revision_number) do nothing;
create or replace function public.nz_combat_bank_v2(p_session uuid) returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',q.revision_id,'difficulty',q.difficulty,'category',q.tags[1],'prompt',q.prompt,'options',q.options_json,'correct',q.correct_option_id,'affinity',q.explanation_json->'affinity') order by q.logical_question_id),'[]'::jsonb) from private.questions q join private.game_sessions s on s.id=p_session join public.rooms r on r.id=s.room_id where q.status='ACTIVE' and q.content_version='production-v1' and q.reviewed_at is not null and ('SCHOOL_'||r.school_level)=any(q.tags) $$; revoke all on function public.nz_combat_bank_v2(uuid) from public,anon,authenticated; grant execute on function public.nz_combat_bank_v2(uuid) to service_role;
do $$ declare lvl text; n integer; d text; begin foreach lvl in array array['SD','SMP','SMA'] loop select count(*) into n from private.questions where status='ACTIVE' and content_version='production-v1' and ('SCHOOL_'||lvl)=any(tags); if n<40 then raise exception 'INSUFFICIENT_SCHOOL_COVERAGE_%',lvl; end if; foreach d in array array['EASY','MEDIUM','HARD'] loop select count(*) into n from private.questions where status='ACTIVE' and content_version='production-v1' and difficulty::text=d and ('SCHOOL_'||lvl)=any(tags); if n<10 then raise exception 'INSUFFICIENT_SCHOOL_DIFFICULTY_%_%',lvl,d; end if; end loop; end loop; end $$;
